{"command":"cd "$HOME/aesbuild" && cat > aesgcm.c << 'EOF'
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <openssl/evp.h>

static PyObject *aesgcm_encrypt(PyObject *self, PyObject *args) {
    Py_buffer key, nonce, pt, aad;
    int has_aad = 1;
    if (!PyArg_ParseTuple(args, "y*y*y*y*", &key, &nonce, &pt, &aad)) {
        return NULL;
    }

    const EVP_CIPHER *cipher = NULL;
    if (key.len == 16) cipher = EVP_aes_128_gcm();
    else if (key.len == 24) cipher = EVP_aes_192_gcm();
    else if (key.len == 32) cipher = EVP_aes_256_gcm();
    else {
        PyBuffer_Release(&key); PyBuffer_Release(&nonce);
        PyBuffer_Release(&pt); PyBuffer_Release(&aad);
        PyErr_SetString(PyExc_ValueError, "bad key size");
        return NULL;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        PyBuffer_Release(&key); PyBuffer_Release(&nonce);
        PyBuffer_Release(&pt); PyBuffer_Release(&aad);
        return PyErr_NoMemory();
    }

    int ok = 1;
    PyObject *ct = NULL;
    PyObject *tag = NULL;
    unsigned char *ctbuf = NULL;
    unsigned char tagbuf[16];
    int outlen = 0, total = 0;

    if (EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL) != 1) ok = 0;
    if (ok && EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, (int)nonce.len, NULL) != 1) ok = 0;
    if (ok && EVP_EncryptInit_ex(ctx, NULL, NULL, key.buf, nonce.buf) != 1) ok = 0;
    if (ok && aad.len > 0) {
        if (EVP_EncryptUpdate(ctx, NULL, &outlen, aad.buf, (int)aad.len) != 1) ok = 0;
    }
    if (ok) {
        ct = PyBytes_FromStringAndSize(NULL, pt.len);
        if (!ct) ok = 0;
        else ctbuf = (unsigned char *)PyBytes_AS_STRING(ct);
    }
    if (ok && EVP_EncryptUpdate(ctx, ctbuf, &outlen, pt.buf, (int)pt.len) != 1) ok = 0;
    if (ok) {
        total = outlen;
        if (EVP_EncryptFinal_ex(ctx, ctbuf + total, &outlen) != 1) ok = 0;
        total += outlen;
    }
    if (ok && EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tagbuf) != 1) ok = 0;
    if (ok) {
        tag = PyBytes_FromStringAndSize((char *)tagbuf, 16);
        if (!tag) ok = 0;
    }
    if (ok && total != pt.len) {
        /* resize if needed; GCM ciphertext length equals plaintext */
        if (_PyBytes_Resize(&ct, total) < 0) ok = 0;
    }

    EVP_CIPHER_CTX_free(ctx);
    PyBuffer_Release(&key);
    PyBuffer_Release(&nonce);
    PyBuffer_Release(&pt);
    PyBuffer_Release(&aad);

    if (!ok) {
        Py_XDECREF(ct);
        Py_XDECREF(tag);
        if (!PyErr_Occurred())
            PyErr_SetString(PyExc_RuntimeError, "AES-GCM encrypt failed");
        return NULL;
    }
    return Py_BuildValue("NN", ct, tag);
}

static PyMethodDef methods[] = {
    {"encrypt", aesgcm_encrypt, METH_VARARGS, "AES-GCM encrypt"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "aesgcm_ext", NULL, -1, methods
};

PyMODINIT_FUNC PyInit_aesgcm_ext(void) {
    return PyModule_Create(&moduledef);
}
EOF
