{"command":"cd "$HOME/aesbuild" && cat > bench.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/evp.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main() {
    size_t n = 60000 * 1024;
    unsigned char *pt = malloc(n);
    unsigned char *ct = malloc(n + 32);
    unsigned char key[16], iv[12], aad[32], tag[16];
    memset(pt, 1, n);
    memset(key, 2, 16);
    memset(iv, 3, 12);
    memset(aad, 4, 32);

    const EVP_CIPHER *cipher = EVP_aes_128_gcm();
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();

    /* warmup */
    int outlen, total;
    EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
    EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
    EVP_EncryptUpdate(ctx, ct, &outlen, pt, (int)n);
    total = outlen;
    EVP_EncryptFinal_ex(ctx, ct + total, &outlen);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);

    double t0 = now();
    int reps = 10;
    for (int i = 0; i < reps; i++) {
        EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
        EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
        EVP_EncryptUpdate(ctx, ct, &outlen, pt, (int)n);
        total = outlen;
        EVP_EncryptFinal_ex(ctx, ct + total, &outlen);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    }
    double dt = (now() - t0) / reps;
    printf("full %.6f s  %.1f MB/s\n", dt, (n/1e6)/dt);

    /* just update after init */
    EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
    EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
    t0 = now();
    EVP_EncryptUpdate(ctx, ct, &outlen, pt, (int)n);
    dt = now() - t0;
    printf("update only %.6f s  %.1f MB/s outlen=%d\n", dt, (n/1e6)/dt, outlen);

    /* CTR-like: AES-CTR via EVP for comparison */
    const EVP_CIPHER *ctr = EVP_aes_128_ctr();
    unsigned char iv16[16] = {0};
    memcpy(iv16, iv, 12);
    EVP_EncryptInit_ex(ctx, ctr, NULL, key, iv16);
    t0 = now();
    EVP_EncryptUpdate(ctx, ct, &outlen, pt, (int)n);
    dt = now() - t0;
    printf("ctr update %.6f s  %.1f MB/s\n", dt, (n/1e6)/dt);

    /* raw AES ecb block */
    EVP_CIPHER_CTX *bctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(bctx, EVP_aes_128_ecb(), NULL, key, NULL);
    EVP_CIPHER_CTX_set_padding(bctx, 0);
    t0 = now();
    EVP_EncryptUpdate(bctx, ct, &outlen, pt, (int)n);
    dt = now() - t0;
    printf("ecb update %.6f s  %.1f MB/s\n", dt, (n/1e6)/dt);

    return 0;
}
EOF
cc -O3 -I/usr/local/opt/openssl@3/include -L/usr/local/opt/openssl@3/lib -o bench bench.c -lcrypto && ./bench"}

