#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <openssl/evp.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main() {
    size_t n = 60000UL * 1024;
    unsigned char *pt = malloc(n);
    unsigned char *ct = malloc(n);
    unsigned char key[16], iv[12], aad[32], tag[16];
    memset(pt, 1, n);
    memset(key, 2, 16);
    memset(iv, 3, 12);
    memset(aad, 4, 32);
    const EVP_CIPHER *cipher = EVP_aes_128_gcm();
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int outlen;

    /* chunked updates */
    size_t chunks[] = {4096, 16384, 65536, 1024*1024, 4*1024*1024, 16*1024*1024, n};
    int nc = sizeof(chunks)/sizeof(chunks[0]);
    for (int c = 0; c < nc; c++) {
        size_t ch = chunks[c];
        double t0 = now();
        int reps = 3;
        for (int r = 0; r < reps; r++) {
            EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
            EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
            EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
            size_t off = 0;
            while (off < n) {
                int len = (int)((n - off) > ch ? ch : (n - off));
                EVP_EncryptUpdate(ctx, ct + off, &outlen, pt + off, len);
                off += len;
            }
            EVP_EncryptFinal_ex(ctx, ct, &outlen);
            EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
        }
        double dt = (now()-t0)/reps;
        printf("chunk %8zu  %.6f s  %.1f MB/s\n", ch, dt, (n/1e6)/dt);
    }
    return 0;
}
EOF
