#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/aes.h>
#include <openssl/modes.h>

/* from openssl crypto/modes/aes-gcm-avx512.pl / gcm128.c */
size_t aesni_gcm_encrypt(const unsigned char *in, unsigned char *out, size_t len,
                         const void *key, unsigned char ivec[16], unsigned char Htable[256],
                         unsigned int *Xi);

void aesni_encrypt(const unsigned char *in, unsigned char *out, const AES_KEY *key);
int aesni_set_encrypt_key(const unsigned char *userKey, int bits, AES_KEY *key);

/* GHASH init */
void gcm_init_clmul(unsigned char Htable[16*16], const unsigned long long Xi[2]);
void gcm_ghash_clmul(unsigned long long Xi[2], const unsigned char Htable[16*16],
                     const unsigned char *inp, size_t len);
void gcm_gmult_clmul(unsigned long long Xi[2], const unsigned char Htable[16*16]);

/* also avx variants */
void gcm_init_avx(unsigned char Htable[16*16], const unsigned long long Xi[2]);

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

int main() {
    size_t n = 60000UL * 1024;
    /* align to 16 */
    unsigned char *pt = aligned_alloc(64, n);
    unsigned char *ct = aligned_alloc(64, n);
    memset(pt, 0x11, n);
    unsigned char keyb[16];
    memset(keyb, 0x22, 16);
    AES_KEY key;
    aesni_set_encrypt_key(keyb, 128, &key);

    unsigned char H[16];
    unsigned char zero[16] = {0};
    aesni_encrypt(zero, H, &key);

    unsigned char Htable[16*16];
    /* try both inits */
    unsigned long long Hll[2];
    memcpy(Hll, H, 16);
    gcm_init_avx(Htable, Hll);

    unsigned char ivec[16];
    memset(ivec, 0, 16);
    /* nonce 12 bytes of 3s, counter = 1? GCM typically starts counter at 1 for J0 then increments to 2 for first block.
       aesni_gcm_encrypt expects ivec already set to the initial counter. We'll experiment. */
    memset(ivec, 3, 12);
    ivec[15] = 2; /* common: J0 has counter 1, first data block uses 2 */

    unsigned int Xi[4] = {0};

    double t0 = now();
    size_t ret = aesni_gcm_encrypt(pt, ct, n, &key, ivec, Htable, Xi);
    double dt = now()-t0;
    printf("ret %zu time %.6f MB/s %.1f ivec_after[12..15]=%02x%02x%02x%02x Xi0=%08x\n",
           ret, dt, (n/1e6)/dt, ivec[12], ivec[13], ivec[14], ivec[15], Xi[0]);

    /* second call timing only */
    memset(ivec, 3, 12); ivec[15]=2;
    memset(Xi, 0, sizeof(Xi));
    t0 = now();
    aesni_gcm_encrypt(pt, ct, n, &key, ivec, Htable, Xi);
    dt = now()-t0;
    printf("2nd %.6f MB/s %.1f\n", dt, (n/1e6)/dt);
    return 0;
}
EOF
