{"command":"cd "$HOME/aesbuild" && cat > vaes.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <immintrin.h>
#include <openssl/evp.h>

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

/* AES-128 key schedule, AES-NI */
static inline __m128i aes128_keyexp(__m128i k, __m128i k2) {
    k2 = _mm_shuffle_epi32(k2, _MM_SHUFFLE(3,3,3,3));
    k = _mm_xor_si128(k, _mm_slli_si128(k, 4));
    k = _mm_xor_si128(k, _mm_slli_si128(k, 4));
    k = _mm_xor_si128(k, _mm_slli_si128(k, 4));
    return _mm_xor_si128(k, k2);
}

static void expand128(const unsigned char *key, __m128i rk[11]) {
    rk[0] = _mm_loadu_si128((const __m128i*)key);
    rk[1] = aes128_keyexp(rk[0], _mm_aeskeygenassist_si128(rk[0], 0x01));
    rk[2] = aes128_keyexp(rk[1], _mm_aeskeygenassist_si128(rk[1], 0x02));
    rk[3] = aes128_keyexp(rk[2], _mm_aeskeygenassist_si128(rk[2], 0x04));
    rk[4] = aes128_keyexp(rk[3], _mm_aeskeygenassist_si128(rk[3], 0x08));
    rk[5] = aes128_keyexp(rk[4], _mm_aeskeygenassist_si128(rk[4], 0x10));
    rk[6] = aes128_keyexp(rk[5], _mm_aeskeygenassist_si128(rk[5], 0x20));
    rk[7] = aes128_keyexp(rk[6], _mm_aeskeygenassist_si128(rk[6], 0x40));
    rk[8] = aes128_keyexp(rk[7], _mm_aeskeygenassist_si128(rk[7], 0x80));
    rk[9] = aes128_keyexp(rk[8], _mm_aeskeygenassist_si128(rk[8], 0x1b));
    rk[10]= aes128_keyexp(rk[9], _mm_aeskeygenassist_si128(rk[9], 0x36));
}

/* encrypt 8 blocks (128 bytes) with independent counters, CTR mode */
static void aes128_ctr8(const __m128i rk[11], __m128i ctr,
                        unsigned char *out, const unsigned char *in) {
    __m128i b0 = _mm_xor_si128(ctr, rk[0]);
    __m128i one = _mm_set_epi32(0,0,0,1);
    __m128i c1 = _mm_add_epi32(ctr, one);
    __m128i b1 = _mm_xor_si128(c1, rk[0]);
    __m128i c2 = _mm_add_epi32(c1, one);
    __m128i b2 = _mm_xor_si128(c2, rk[0]);
    __m128i c3 = _mm_add_epi32(c2, one);
    __m128i b3 = _mm_xor_si128(c3, rk[0]);
    __m128i c4 = _mm_add_epi32(c3, one);
    __m128i b4 = _mm_xor_si128(c4, rk[0]);
    __m128i c5 = _mm_add_epi32(c4, one);
    __m128i b5 = _mm_xor_si128(c5, rk[0]);
    __m128i c6 = _mm_add_epi32(c5, one);
    __m128i b6 = _mm_xor_si128(c6, rk[0]);
    __m128i c7 = _mm_add_epi32(c6, one);
    __m128i b7 = _mm_xor_si128(c7, rk[0]);

    #define ROUND(i) \
        b0 = _mm_aesenc_si128(b0, rk[i]); \
        b1 = _mm_aesenc_si128(b1, rk[i]); \
        b2 = _mm_aesenc_si128(b2, rk[i]); \
        b3 = _mm_aesenc_si128(b3, rk[i]); \
        b4 = _mm_aesenc_si128(b4, rk[i]); \
        b5 = _mm_aesenc_si128(b5, rk[i]); \
        b6 = _mm_aesenc_si128(b6, rk[i]); \
        b7 = _mm_aesenc_si128(b7, rk[i]);
    ROUND(1) ROUND(2) ROUND(3) ROUND(4) ROUND(5)
    ROUND(6) ROUND(7) ROUND(8) ROUND(9)
    #undef ROUND
    b0 = _mm_aesenclast_si128(b0, rk[10]);
    b1 = _mm_aesenclast_si128(b1, rk[10]);
    b2 = _mm_aesenclast_si128(b2, rk[10]);
    b3 = _mm_aesenclast_si128(b3, rk[10]);
    b4 = _mm_aesenclast_si128(b4, rk[10]);
    b5 = _mm_aesenclast_si128(b5, rk[10]);
    b6 = _mm_aesenclast_si128(b6, rk[10]);
    b7 = _mm_aesenclast_si128(b7, rk[10]);

    __m128i p0 = _mm_loadu_si128((const __m128i*)in);
    __m128i p1 = _mm_loadu_si128((const __m128i*)in+1);
    __m128i p2 = _mm_loadu_si128((const __m128i*)in+2);
    __m128i p3 = _mm_loadu_si128((const __m128i*)in+3);
    __m128i p4 = _mm_loadu_si128((const __m128i*)in+4);
    __m128i p5 = _mm_loadu_si128((const __m128i*)in+5);
    __m128i p6 = _mm_loadu_si128((const __m128i*)in+6);
    __m128i p7 = _mm_loadu_si128((const __m128i*)in+7);
    _mm_storeu_si128((__m128i*)out,   _mm_xor_si128(b0, p0));
    _mm_storeu_si128((__m128i*)out+1, _mm_xor_si128(b1, p1));
    _mm_storeu_si128((__m128i*)out+2, _mm_xor_si128(b2, p2));
    _mm_storeu_si128((__m128i*)out+3, _mm_xor_si128(b3, p3));
    _mm_storeu_si128((__m128i*)out+4, _mm_xor_si128(b4, p4));
    _mm_storeu_si128((__m128i*)out+5, _mm_xor_si128(b5, p5));
    _mm_storeu_si128((__m128i*)out+6, _mm_xor_si128(b6, p6));
    _mm_storeu_si128((__m128i*)out+7, _mm_xor_si128(b7, p7));
}

/* 4-way for comparison */
static void aes128_ctr4(const __m128i rk[11], __m128i ctr,
                        unsigned char *out, const unsigned char *in) {
    __m128i one = _mm_set_epi32(0,0,0,1);
    __m128i b0 = _mm_xor_si128(ctr, rk[0]);
    __m128i c1 = _mm_add_epi32(ctr, one); __m128i b1 = _mm_xor_si128(c1, rk[0]);
    __m128i c2 = _mm_add_epi32(c1, one);  __m128i b2 = _mm_xor_si128(c2, rk[0]);
    __m128i c3 = _mm_add_epi32(c2, one);  __m128i b3 = _mm_xor_si128(c3, rk[0]);
    for (int i = 1; i <= 9; i++) {
        b0 = _mm_aesenc_si128(b0, rk[i]);
        b1 = _mm_aesenc_si128(b1, rk[i]);
        b2 = _mm_aesenc_si128(b2, rk[i]);
        b3 = _mm_aesenc_si128(b3, rk[i]);
    }
    b0 = _mm_aesenclast_si128(b0, rk[10]);
    b1 = _mm_aesenclast_si128(b1, rk[10]);
    b2 = _mm_aesenclast_si128(b2, rk[10]);
    b3 = _mm_aesenclast_si128(b3, rk[10]);
    _mm_storeu_si128((__m128i*)out,   _mm_xor_si128(b0, _mm_loadu_si128((const __m128i*)in)));
    _mm_storeu_si128((__m128i*)out+1, _mm_xor_si128(b1, _mm_loadu_si128((const __m128i*)in+1)));
    _mm_storeu_si128((__m128i*)out+2, _mm_xor_si128(b2, _mm_loadu_si128((const __m128i*)in+2)));
    _mm_storeu_si128((__m128i*)out+3, _mm_xor_si128(b3, _mm_loadu_si128((const __m128i*)in+3)));
}

int main() {
    size_t n = 60000UL * 1024;
    unsigned char *pt = aligned_alloc(64, n);
    unsigned char *ct = aligned_alloc(64, n);
    memset(pt, 1, n);
    unsigned char keyb[16]; memset(keyb, 2, 16);
    __m128i rk[11];
    expand128(keyb, rk);

    /* counter big-endian increment: we'll use a simple little-endian add for throughput test only */
    __m128i ctr = _mm_setzero_si128();
    __m128i eight = _mm_set_epi32(0,0,0,8);
    __m128i four = _mm_set_epi32(0,0,0,4);

    /* warmup */
    for (size_t off = 0; off < n; off += 128) {
        aes128_ctr8(rk, ctr, ct+off, pt+off);
        ctr = _mm_add_epi32(ctr, eight);
    }

    ctr = _mm_setzero_si128();
    double t0 = now();
    for (size_t off = 0; off < n; off += 128) {
        aes128_ctr8(rk, ctr, ct+off, pt+off);
        ctr = _mm_add_epi32(ctr, eight);
    }
    double dt = now()-t0;
    printf("ctr8 %.6f s  %.1f MB/s\n", dt, (n/1e6)/dt);

    ctr = _mm_setzero_si128();
    t0 = now();
    for (size_t off = 0; off < n; off += 64) {
        aes128_ctr4(rk, ctr, ct+off, pt+off);
        ctr = _mm_add_epi32(ctr, four);
    }
