{"command":"cd "$HOME/aesbuild" && cat > vaes2.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <immintrin.h>
#include <pthread.h>

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

static inline __m128i aes128_keyexp(__m128i k, __m128i k2) {
    k2 = _mm_shuffle_epi32(k2, _MM_SHUFFLE(3,3,3,3));
    k = _mm_xor_si128(k, _mm_slli_si128(k, 4));
    k = _mm_xor_si128(k, _mm_slli_si128(k, 4));
    k = _mm_xor_si128(k, _mm_slli_si128(k, 4));
    return _mm_xor_si128(k, k2);
}
static void expand128(const unsigned char *key, __m128i rk[11]) {
    rk[0] = _mm_loadu_si128((const __m128i*)key);
    rk[1] = aes128_keyexp(rk[0], _mm_aeskeygenassist_si128(rk[0], 0x01));
    rk[2] = aes128_keyexp(rk[1], _mm_aeskeygenassist_si128(rk[1], 0x02));
    rk[3] = aes128_keyexp(rk[2], _mm_aeskeygenassist_si128(rk[2], 0x04));
    rk[4] = aes128_keyexp(rk[3], _mm_aeskeygenassist_si128(rk[3], 0x08));
    rk[5] = aes128_keyexp(rk[4], _mm_aeskeygenassist_si128(rk[4], 0x10));
    rk[6] = aes128_keyexp(rk[5], _mm_aeskeygenassist_si128(rk[5], 0x20));
    rk[7] = aes128_keyexp(rk[6], _mm_aeskeygenassist_si128(rk[6], 0x40));
    rk[8] = aes128_keyexp(rk[7], _mm_aeskeygenassist_si128(rk[7], 0x80));
    rk[9] = aes128_keyexp(rk[8], _mm_aeskeygenassist_si128(rk[8], 0x1b));
    rk[10]= aes128_keyexp(rk[9], _mm_aeskeygenassist_si128(rk[9], 0x36));
}

/* 8-way but keep round keys in regs by using a function that compiler can schedule.
   Process 256 bytes (16 blocks) per call to increase ILP. */
static void aes128_ctr16(const __m128i rk[11], __m128i ctr,
                         unsigned char *out, const unsigned char *in) {
    __m128i one = _mm_set_epi32(0,0,0,1);
    __m128i b[16];
    __m128i c = ctr;
    for (int i = 0; i < 16; i++) {
        b[i] = _mm_xor_si128(c, rk[0]);
        c = _mm_add_epi32(c, one);
    }
    for (int r = 1; r <= 9; r++) {
        for (int i = 0; i < 16; i++) b[i] = _mm_aesenc_si128(b[i], rk[r]);
    }
    for (int i = 0; i < 16; i++) b[i] = _mm_aesenclast_si128(b[i], rk[10]);
    for (int i = 0; i < 16; i++) {
        __m128i p = _mm_loadu_si128((const __m128i*)in + i);
        _mm_storeu_si128((__m128i*)out + i, _mm_xor_si128(b[i], p));
    }
}

typedef struct {
    const __m128i *rk;
    unsigned char *ct;
    const unsigned char *pt;
    size_t start, end; /* byte offsets, multiple of 16 */
    unsigned int ctr0; /* starting counter value (LE for this bench) */
} job_t;

static void *worker(void *arg) {
    job_t *j = arg;
    __m128i one = _mm_set_epi32(0,0,0,1);
    __m128i ctr = _mm_set_epi32(0,0,0, j->ctr0);
    size_t off = j->start;
    /* 8-block chunks */
    __m128i eight = _mm_set_epi32(0,0,0,8);
    while (off + 128 <= j->end) {
        __m128i b0,b1,b2,b3,b4,b5,b6,b7;
        __m128i c = ctr;
        b0 = _mm_xor_si128(c, j->rk[0]); c = _mm_add_epi32(c, one);
        b1 = _mm_xor_si128(c, j->rk[0]); c = _mm_add_epi32(c, one);
        b2 = _mm_xor_si128(c, j->rk[0]); c = _mm_add_epi32(c, one);
        b3 = _mm_xor_si128(c, j->rk[0]); c = _mm_add_epi32(c, one);
        b4 = _mm_xor_si128(c, j->rk[0]); c = _mm_add_epi32(c, one);
        b5 = _mm_xor_si128(c, j->rk[0]); c = _mm_add_epi32(c, one);
        b6 = _mm_xor_si128(c, j->rk[0]); c = _mm_add_epi32(c, one);
        b7 = _mm_xor_si128(c, j->rk[0]);
        for (int r = 1; r <= 9; r++) {
            __m128i k = j->rk[r];
            b0 = _mm_aesenc_si128(b0, k);
            b1 = _mm_aesenc_si128(b1, k);
            b2 = _mm_aesenc_si128(b2, k);
            b3 = _mm_aesenc_si128(b3, k);
            b4 = _mm_aesenc_si128(b4, k);
            b5 = _mm_aesenc_si128(b5, k);
            b6 = _mm_aesenc_si128(b6, k);
            b7 = _mm_aesenc_si128(b7, k);
        }
        __m128i k = j->rk[10];
        b0 = _mm_aesenclast_si128(b0, k);
        b1 = _mm_aesenclast_si128(b1, k);
        b2 = _mm_aesenclast_si128(b2, k);
        b3 = _mm_aesenclast_si128(b3, k);
        b4 = _mm_aesenclast_si128(b4, k);
        b5 = _mm_aesenclast_si128(b5, k);
        b6 = _mm_aesenclast_si128(b6, k);
        b7 = _mm_aesenclast_si128(b7, k);
        unsigned char *out = j->ct + off;
        const unsigned char *in = j->pt + off;
        _mm_storeu_si128((__m128i*)out+0, _mm_xor_si128(b0, _mm_loadu_si128((const __m128i*)in+0)));
        _mm_storeu_si128((__m128i*)out+1, _mm_xor_si128(b1, _mm_loadu_si128((const __m128i*)in+1)));
        _mm_storeu_si128((__m128i*)out+2, _mm_xor_si128(b2, _mm_loadu_si128((const __m128i*)in+2)));
        _mm_storeu_si128((__m128i*)out+3, _mm_xor_si128(b3, _mm_loadu_si128((const __m128i*)in+3)));
        _mm_storeu_si128((__m128i*)out+4, _mm_xor_si128(b4, _mm_loadu_si128((const __m128i*)in+4)));
        _mm_storeu_si128((__m128i*)out+5, _mm_xor_si128(b5, _mm_loadu_si128((const __m128i*)in+5)));
        _mm_storeu_si128((__m128i*)out+6, _mm_xor_si128(b6, _mm_loadu_si128((const __m128i*)in+6)));
        _mm_storeu_si128((__m128i*)out+7, _mm_xor_si128(b7, _mm_loadu_si128((const __m128i*)in+7)));
        off += 128;
        ctr = _mm_add_epi32(ctr, eight);
    }
    return NULL;
}

int main() {
    size_t n = 60000UL * 1024;
    unsigned char *pt = aligned_alloc(64, n);
    unsigned char *ct = aligned_alloc(64, n);
    memset(pt, 1, n);
    unsigned char keyb[16]; memset(keyb, 2, 16);
    __m128i rk[11];
    expand128(keyb, rk);

    /* single thread 16-way */
    __m128i ctr = _mm_setzero_si128();
    __m128i sixteen = _mm_set_epi32(0,0,0,16);
    double t0 = now();
    for (size_t off = 0; off < n; off += 256) {
        aes128_ctr16(rk, ctr, ct+off, pt+off);
        ctr = _mm_add_epi32(ctr, sixteen);
    }
    double dt = now()-t0;
    printf("ctr16 %.6f s %.1f MB/s\n", dt, (n/1e6)/dt);

    for (int nth = 1; nth <= 6; nth++) {
        job_t jobs[8];
        pthread_t th[8];
        size_t chunk = (n / nth) & ~127UL;
        t0 = now();
        for (int i = 0; i < nth; i++) {
            jobs[i].rk = rk;
            jobs[i].ct = ct;
            jobs[i].pt = pt;
            jobs[i].start = i * chunk;
            jobs[i].end = (i == nth-1) ? n : (i+1)*chunk;
            jobs[i].ctr0 = (unsigned)(jobs[i].start / 16);
            pthread_create(&th[i], NULL, worker, &jobs[i]);
        }
        for (int i = 0; i < nth; i++) pthread_join(th[i], NULL);
        dt = now()-t0;
        printf("threads %d %.6f s %.1f MB/s\n", nth, dt, (n/1e6)/dt);
    }
    return 0;
}
EOF
cc -O3 -maes -mpclmul -mavx2 -pthread -o vaes2 vaes2.c && ./vaes2"}

