#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <openssl/evp.h>

static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}

typedef struct {
    unsigned char *ct, *pt;
    size_t start, len;
    unsigned char key[16];
    unsigned char iv[16];
} job;

static void *worker(void *arg) {
    job *j = arg;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int outlen;
    EVP_EncryptInit_ex(ctx, EVP_aes_128_ctr(), NULL, j->key, j->iv);
    EVP_EncryptUpdate(ctx, j->ct + j->start, &outlen, j->pt + j->start, (int)j->len);
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

int main() {
    size_t n = 60000UL*1024;
    unsigned char *pt = malloc(n);
    unsigned char *ct = malloc(n);
    memset(pt, 1, n);
    unsigned char key[16]; memset(key, 2, 16);

