        job jobs[8];
        pthread_t th[8];
        size_t chunk = n / nth;
        /* align to 16 */
        chunk &= ~15UL;
        double t0 = now();
        int reps = 3;
        for (int r = 0; r < reps; r++) {
            for (int i = 0; i < nth; i++) {
                jobs[i].ct = ct; jobs[i].pt = pt;
                jobs[i].start = i * chunk;
                jobs[i].len = (i == nth-1) ? (n - jobs[i].start) : chunk;
                memcpy(jobs[i].key, key, 16);
                memset(jobs[i].iv, 0, 16);
                /* counter offset = start/16, big-endian in last 4 bytes roughly */
                unsigned int c = (unsigned)(jobs[i].start / 16);
                jobs[i].iv[12] = (c>>24)&0xff;
                jobs[i].iv[13] = (c>>16)&0xff;
                jobs[i].iv[14] = (c>>8)&0xff;
                jobs[i].iv[15] = c&0xff;
                pthread_create(&th[i], NULL, worker, &jobs[i]);
            }
            for (int i = 0; i < nth; i++) pthread_join(th[i], NULL);
        }
        double dt = (now()-t0)/reps;
        printf("evp threads %d  %.6f s  %.1f MB/s\n", nth, dt, (n/1e6)/dt);
    }
    return 0;
}
