/* GCM multiplication in the reflected representation used by Intel CLMUL.
   Standard approach from Intel whitepaper:
   - bit-reflect bytes (or use pclmul on reflected polynomials)
   We'll implement the classic non-reflected shift-based multiply first for correctness,
   then a pclmul version. */

static void xor16(uint8_t *a, const uint8_t *b){ for(int i=0;i<16;i++) a[i]^=b[i]; }

/* multiply two 128-bit values in GHASH field (no reflection): 
   left-shift convention, reduction poly x^128 + x^7 + x^2 + x + 1
   as in NIST SP 800-38D. */
static void gcm_mul(uint8_t x[16], const uint8_t h[16]) {
    uint8_t z[16] = {0};
    uint8_t v[16];
    memcpy(v, h, 16);
    for (int i = 0; i < 16; i++) {
        for (int bit = 7; bit >= 0; bit--) {
            if ((x[i] >> bit) & 1) xor16(z, v);
            /* v = v >> 1 (right shift across bytes), xor reduction if lsb was 1 */
            int lsb = v[15] & 1;
            for (int j = 15; j > 0; j--) v[j] = (v[j] >> 1) | (v[j-1] << 7);
            v[0] >>= 1;
            if (lsb) v[0] ^= 0xe1;
        }
    }
    memcpy(x, z, 16);
}

static void ghash(uint8_t y[16], const uint8_t h[16], const uint8_t *data, size_t len) {
    for (size_t i = 0; i < len; i += 16) {
        uint8_t block[16] = {0};
        size_t n = len - i; if (n > 16) n = 16;
        memcpy(block, data+i, n);
        xor16(y, block);
        gcm_mul(y, h);
    }
}

int main() {
    unsigned char key[16]={0}, nonce[12]={0};
    unsigned char pt[16]; for (int i=0;i<16;i++) pt[i]=i;
    unsigned char aad[8]={1,2,3,4,5,6,7,8};
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    unsigned char ct[16], tag[16]; int outlen;
    EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
    EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 8);
    EVP_EncryptUpdate(ctx, ct, &outlen, pt, 16);
    EVP_EncryptFinal_ex(ctx, ct, &outlen);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);

    unsigned char H[16]={0}, zero[16]={0};
    EVP_CIPHER_CTX *e = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(e, EVP_aes_128_ecb(), NULL, key, NULL);
    EVP_CIPHER_CTX_set_padding(e, 0);
    EVP_EncryptUpdate(e, H, &outlen, zero, 16);

