    printf("pred "); for(int i=0;i<16;i++) printf("%02x", pred[i]);
    printf("\ntag  "); for(int i=0;i<16;i++) printf("%02x", tag[i]);
    printf("\nmatch %d\n", memcmp(pred, tag, 16)==0);

