static inline __m128i brev_bytes(__m128i x) {
    const __m128i mask_0f = _mm_set1_epi8(0x0f);
    const __m128i lut = _mm_set_epi8(
        0xf0,0x70,0xb0,0x30,0xd0,0x50,0x90,0x10,
        0xe0,0x60,0xa0,0x20,0xc0,0x40,0x80,0x00);
    /* lut indexed by nibble: index 0 -> 0x00, 1 -> 0x80, ... stored reversed in set_epi8
       _mm_set_epi8(b15..b0), so b0 is low byte = 0x00 which is index 0. Wait set_epi8 last arg is byte 0.
       I passed 0x00 as last arg, so byte0=0x00, byte1=0x80, byte2=0x40, ... yes that's bitreverse nibble << 4.
       But shuffle_epi8 uses low nibble of each byte as index into the 16-byte register. Good. */
    __m128i lo = _mm_and_si128(x, mask_0f);
    __m128i hi = _mm_and_si128(_mm_srli_epi16(x, 4), mask_0f);
    lo = _mm_shuffle_epi8(lut, lo);          /* low nibble reflected into high nibble */
    hi = _mm_shuffle_epi8(lut, hi);          /* high nibble reflected into high nibble */
    hi = _mm_srli_epi16(hi, 4);              /* move to low nibble */
    return _mm_or_si128(lo, hi);
}

static inline __m128i reflect(__m128i x) {
    /* bit-reverse all 128 bits: reverse bytes then reverse bits in each byte */
    return brev_bytes(bswap128(x));
}

static inline __m128i gfmul(__m128i a, __m128i b) {
    __m128i tmp2, tmp3, tmp4, tmp5, tmp6, tmp7, tmp8, tmp9;
    tmp3 = _mm_clmulepi64_si128(a, b, 0x00);
    tmp4 = _mm_clmulepi64_si128(a, b, 0x10);
    tmp5 = _mm_clmulepi64_si128(a, b, 0x01);
    tmp6 = _mm_clmulepi64_si128(a, b, 0x11);
    tmp4 = _mm_xor_si128(tmp4, tmp5);
    tmp5 = _mm_slli_si128(tmp4, 8);
    tmp4 = _mm_srli_si128(tmp4, 8);
    tmp3 = _mm_xor_si128(tmp3, tmp5);
    tmp6 = _mm_xor_si128(tmp6, tmp4);
    tmp7 = _mm_srli_epi32(tmp3, 31);
    tmp8 = _mm_srli_epi32(tmp6, 31);
    tmp3 = _mm_slli_epi32(tmp3, 1);
    tmp6 = _mm_slli_epi32(tmp6, 1);
    tmp9 = _mm_srli_si128(tmp7, 12);
    tmp8 = _mm_slli_si128(tmp8, 4);
    tmp7 = _mm_slli_si128(tmp7, 4);
    tmp3 = _mm_or_si128(tmp3, tmp7);
    tmp6 = _mm_or_si128(tmp6, tmp8);
    tmp6 = _mm_or_si128(tmp6, tmp9);
    tmp7 = _mm_slli_epi32(tmp3, 31);
    tmp8 = _mm_slli_epi32(tmp3, 30);
    tmp9 = _mm_slli_epi32(tmp3, 25);
    tmp7 = _mm_xor_si128(tmp7, tmp8);
    tmp7 = _mm_xor_si128(tmp7, tmp9);
    tmp8 = _mm_srli_si128(tmp7, 4);
    tmp7 = _mm_slli_si128(tmp7, 12);
    tmp3 = _mm_xor_si128(tmp3, tmp7);
    tmp2 = _mm_srli_epi32(tmp3, 1);
    tmp4 = _mm_srli_epi32(tmp3, 2);
    tmp5 = _mm_srli_epi32(tmp3, 7);
    tmp2 = _mm_xor_si128(tmp2, tmp4);
    tmp2 = _mm_xor_si128(tmp2, tmp5);
    tmp2 = _mm_xor_si128(tmp2, tmp8);
    tmp3 = _mm_xor_si128(tmp3, tmp2);
    tmp6 = _mm_xor_si128(tmp6, tmp3);
    return tmp6;
}

static void dump(const char *s, const uint8_t *p) {
    printf("%s ", s); for (int i=0;i<16;i++) printf("%02x", p[i]); printf("\n");
}

int main() {
    /* verify bit reverse of a byte */
    uint8_t b = 0x01;
    __m128i x = _mm_set1_epi8(b);
    __m128i y = brev_bytes(x);
    uint8_t outb[16]; _mm_storeu_si128((__m128i*)outb, y);
    printf("brev 0x01 -> %02x (expect 80)\n", outb[0]);
    x = _mm_set1_epi8(0x80);
    y = brev_bytes(x);
    _mm_storeu_si128((__m128i*)outb, y);
    printf("brev 0x80 -> %02x (expect 01)\n", outb[0]);

    unsigned char key[16]={0}, nonce[12]={0};
    unsigned char pt[16]; for (int i=0;i<16;i++) pt[i]=i;
    unsigned char aad[8]={1,2,3,4,5,6,7,8};
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    unsigned char ct[16], tag[16]; int outlen;
    EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
    EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 8);
