    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);

    unsigned char H[16]={0}, zero[16]={0};
    EVP_CIPHER_CTX *e = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(e, EVP_aes_128_ecb(), NULL, key, NULL);
    EVP_CIPHER_CTX_set_padding(e, 0);
    EVP_EncryptUpdate(e, H, &outlen, zero, 16);
    unsigned char J0[16]={0}; memcpy(J0, nonce, 12); J0[15]=1;
    unsigned char EKJ0[16];
    EVP_EncryptInit_ex(e, EVP_aes_128_ecb(), NULL, key, NULL);
    EVP_CIPHER_CTX_set_padding(e, 0);
    EVP_EncryptUpdate(e, EKJ0, &outlen, J0, 16);

    unsigned char buf[48]; memset(buf,0,48);
    memcpy(buf, aad, 8);
    memcpy(buf+16, ct, 16);
    uint64_t aad_bits=64, ct_bits=128;
    for (int i=0;i<8;i++) { buf[32+i]=(aad_bits>>(56-8*i))&0xff; buf[40+i]=(ct_bits>>(56-8*i))&0xff; }

    __m128i Hh = reflect(_mm_loadu_si128((const __m128i*)H));
    __m128i Y = _mm_setzero_si128();
    for (int i = 0; i < 48; i += 16) {
        __m128i blk = reflect(_mm_loadu_si128((const __m128i*)(buf+i)));
        Y = _mm_xor_si128(Y, blk);
        Y = gfmul(Y, Hh);
    }
    unsigned char S[16];
