    }
    unsigned char ys[16]; _mm_storeu_si128((__m128i*)ys, Y); sink = ys[0];
    double dt = now()-t0;
    printf("ghash+reflect %.6f s %.1f MB/s sink %u\n", dt, (n/1e6)/dt, sink);

    /* pre-reflect data */
    unsigned char *rd = aligned_alloc(64, n);
    for (size_t i = 0; i < n; i += 16) {
        __m128i blk = reflect(_mm_loadu_si128((const __m128i*)(data+i)));
        _mm_storeu_si128((__m128i*)(rd+i), blk);
    }
    t0 = now();
