    for (size_t i = 0; i < n; i += 16) {
        __m128i blk = _mm_loadu_si128((const __m128i*)(rd+i));
        Y = _mm_xor_si128(Y, blk);
        Y = gfmul(Y, Hh);
    }
    _mm_storeu_si128((__m128i*)ys, Y); sink = ys[1];
    dt = now()-t0;
    printf("ghash only    %.6f s %.1f MB/s sink %u\n", dt, (n/1e6)/dt, sink);
    return 0;
}
