    rk[2] = keyexp(rk[1], _mm_aeskeygenassist_si128(rk[1], 0x02));
    rk[3] = keyexp(rk[2], _mm_aeskeygenassist_si128(rk[2], 0x04));
    rk[4] = keyexp(rk[3], _mm_aeskeygenassist_si128(rk[3], 0x08));
    rk[5] = keyexp(rk[4], _mm_aeskeygenassist_si128(rk[4], 0x10));
    rk[6] = keyexp(rk[5], _mm_aeskeygenassist_si128(rk[5], 0x20));
    rk[7] = keyexp(rk[6], _mm_aeskeygenassist_si128(rk[6], 0x40));
    rk[8] = keyexp(rk[7], _mm_aeskeygenassist_si128(rk[7], 0x80));
    rk[9] = keyexp(rk[8], _mm_aeskeygenassist_si128(rk[8], 0x1b));
