/* GHASH using openssl clmul, H must be bswap64'd */
static void ghash_openssl(const uint8_t H[16], const uint8_t *data, size_t len, uint8_t out[16]) {
    uint8_t Hs[16];
    memcpy(Hs, H, 16);
    /* bswap each 64-bit half */
    for (int h=0;h<2;h++) for (int i=0;i<4;i++) { uint8_t t=Hs[h*8+i]; Hs[h*8+i]=Hs[h*8+7-i]; Hs[h*8+7-i]=t; }
    unsigned char Htable[256];
    unsigned long long Hll[2], Xi[2];
    memcpy(Hll, Hs, 16);
    gcm_init_clmul(Htable, Hll);
    Xi[0]=Xi[1]=0;
    /* data length must be multiple of 16 for this call; caller pads */
    gcm_ghash_clmul(Xi, Htable, data, len);
    memcpy(out, Xi, 16);
}

