#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>
#include <immintrin.h>
#include <openssl/evp.h>

void gcm_init_clmul(unsigned char Htable[16*16], const unsigned long long Xi[2]);
void gcm_ghash_clmul(unsigned long long Xi[2], const unsigned char Htable[16*16],
                     const unsigned char *inp, size_t len);

static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}

static inline __m128i keyexp(__m128i k, __m128i k2) {
    k2 = _mm_shuffle_epi32(k2, _MM_SHUFFLE(3,3,3,3));
    k = _mm_xor_si128(k, _mm_slli_si128(k, 4));
    k = _mm_xor_si128(k, _mm_slli_si128(k, 4));
    k = _mm_xor_si128(k, _mm_slli_si128(k, 4));
    return _mm_xor_si128(k, k2);
}
static void expand128(const unsigned char *key, __m128i rk[11]) {
    rk[0] = _mm_loadu_si128((const __m128i*)key);
    rk[1] = keyexp(rk[0], _mm_aeskeygenassist_si128(rk[0], 0x01));
    rk[2] = keyexp(rk[1], _mm_aeskeygenassist_si128(rk[1], 0x02));
    rk[3] = keyexp(rk[2], _mm_aeskeygenassist_si128(rk[2], 0x04));
    rk[4] = keyexp(rk[3], _mm_aeskeygenassist_si128(rk[3], 0x08));
    rk[5] = keyexp(rk[4], _mm_aeskeygenassist_si128(rk[4], 0x10));
    rk[6] = keyexp(rk[5], _mm_aeskeygenassist_si128(rk[5], 0x20));
    rk[7] = keyexp(rk[6], _mm_aeskeygenassist_si128(rk[6], 0x40));
    rk[8] = keyexp(rk[7], _mm_aeskeygenassist_si128(rk[7], 0x80));
    rk[9] = keyexp(rk[8], _mm_aeskeygenassist_si128(rk[8], 0x1b));
    rk[10]= keyexp(rk[9], _mm_aeskeygenassist_si128(rk[9], 0x36));
}
static void aes_block(const __m128i rk[11], const uint8_t in[16], uint8_t out[16]) {
    __m128i b = _mm_loadu_si128((const __m128i*)in);
    b = _mm_xor_si128(b, rk[0]);
    for (int r=1;r<=9;r++) b = _mm_aesenc_si128(b, rk[r]);
    b = _mm_aesenclast_si128(b, rk[10]);
    _mm_storeu_si128((__m128i*)out, b);
