        b2=_mm_aesenclast_si128(b2, rk[10]); b3=_mm_aesenclast_si128(b3, rk[10]);
        uint8_t *out=j->ct+off; const uint8_t *in=j->pt+off;
        _mm_storeu_si128((__m128i*)out+0, _mm_xor_si128(b0, _mm_loadu_si128((const __m128i*)in+0)));
        _mm_storeu_si128((__m128i*)out+1, _mm_xor_si128(b1, _mm_loadu_si128((const __m128i*)in+1)));
        _mm_storeu_si128((__m128i*)out+2, _mm_xor_si128(b2, _mm_loadu_si128((const __m128i*)in+2)));
        _mm_storeu_si128((__m128i*)out+3, _mm_xor_si128(b3, _mm_loadu_si128((const __m128i*)in+3)));
        off += 64; c = _mm_add_epi32(c3, one);
    }
    while (off < j->end) {
        size_t len=j->end-off; if (len>16) len=16;
        __m128i b=_mm_xor_si128(bswap16(c), rk[0]);
        for (int r=1;r<=9;r++) b=_mm_aesenc_si128(b, rk[r]);
        b=_mm_aesenclast_si128(b, rk[10]);
        uint8_t ks[16]; _mm_storeu_si128((__m128i*)ks, b);
        for (size_t i=0;i<len;i++) j->ct[off+i]=j->pt[off+i]^ks[i];
        off += len; c=_mm_add_epi32(c, one);
    }
}
static void *worker(void *a){ ctr_range(a); return NULL; }

static void ghash_ossl(const uint8_t H[16], const uint8_t *data, size_t len, uint8_t out[16]) {
    uint8_t Hs[16]; memcpy(Hs, H, 16);
    for (int h=0;h<2;h++) for (int i=0;i<4;i++) { uint8_t t=Hs[h*8+i]; Hs[h*8+i]=Hs[h*8+7-i]; Hs[h*8+7-i]=t; }
    unsigned char Htable[256];
    unsigned long long Hll[2], Xi[2];
    memcpy(Hll, Hs, 16);
    gcm_init_clmul(Htable, Hll);
    Xi[0]=Xi[1]=0;
    gcm_ghash_clmul(Xi, Htable, data, len);
    memcpy(out, Xi, 16);
}

/* persistent threads */
#define MAXTH 4
static pthread_t ths[MAXTH];
static job_t jobs[MAXTH];
static pthread_mutex_t mu = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv_go = PTHREAD_COND_INITIALIZER;
static pthread_cond_t cv_done = PTHREAD_COND_INITIALIZER;
static int go_flag = 0, die = 0, remaining = 0;
static int nthreads = 2;

static void *pool_worker(void *arg) {
    int id = (int)(intptr_t)arg;
    for (;;) {
        pthread_mutex_lock(&mu);
        while (!go_flag && !die) pthread_cond_wait(&cv_go, &mu);
        if (die) { pthread_mutex_unlock(&mu); break; }
        pthread_mutex_unlock(&mu);
        ctr_range(&jobs[id]);
        pthread_mutex_lock(&mu);
        remaining--;
        if (remaining==0) { go_flag = 0; pthread_cond_signal(&cv_done); }
        pthread_mutex_unlock(&mu);
    }
    return NULL;
}
static void pool_init(int n) {
    nthreads = n;
    for (int i=0;i<n;i++) pthread_create(&ths[i], NULL, pool_worker, (void*)(intptr_t)i);
}
static void pool_run() {
    pthread_mutex_lock(&mu);
    remaining = nthreads;
    go_flag = 1;
    pthread_cond_broadcast(&cv_go);
    while (remaining) pthread_cond_wait(&cv_done, &mu);
    pthread_mutex_unlock(&mu);
}

int main() {
    size_t n = 60000UL*1024;
