        /* For timing, include building gbuf: aad padded (32 already) + ct + len */
        memcpy(gbuf, aad, 32);
        memcpy(gbuf+32, ct, n);
        uint8_t *lb = gbuf+32+n;
        memset(lb, 0, 16);
        uint64_t abits=32*8, cbits=n*8;
        for (int i=0;i<8;i++) { lb[i]=(abits>>(56-8*i))&0xff; lb[8+i]=(cbits>>(56-8*i))&0xff; }
