    }
    double dt = (now()-t0)/reps;
    printf("full path incl memcpy for ghash %.6f s %.1f MB/s tag0=%02x\n", dt, (n/1e6)/dt, tag[0]);

    /* time without the gbuf memcpy: hash ct in place by calling ghash on ct then folding aad.
       GHASH is not easily splittable that way without precomputed H powers, but we can
       hash aad first into Xi then continue on ct. That avoids the big copy. */
    t0 = now();
    for (int r=0;r<reps;r++) {
        for (int i=0;i<nth;i++) {
            jobs[i].rk=rk; jobs[i].ct=ct; jobs[i].pt=pt;
            jobs[i].start=(size_t)i*chunk;
            jobs[i].end=(i==nth-1)?n:(size_t)(i+1)*chunk;
            uint32_t c=2+(uint32_t)(jobs[i].start/16);
            uint8_t cb[16]; memcpy(cb, J0, 12);
            cb[12]=(c>>24)&0xff; cb[13]=(c>>16)&0xff; cb[14]=(c>>8)&0xff; cb[15]=c&0xff;
            jobs[i].ctr_swapped = bswap16(_mm_loadu_si128((const __m128i*)cb));
        }
        pool_run();
        /* incremental ghash */
        uint8_t Hs[16]; memcpy(Hs, H, 16);
        for (int h=0;h<2;h++) for (int i=0;i<4;i++) { uint8_t t=Hs[h*8+i]; Hs[h*8+i]=Hs[h*8+7-i]; Hs[h*8+7-i]=t; }
        unsigned char Htable[256];
        unsigned long long Hll[2], Xi[2]={0,0};
        memcpy(Hll, Hs, 16);
        gcm_init_clmul(Htable, Hll);
        gcm_ghash_clmul(Xi, Htable, aad, 32);
        gcm_ghash_clmul(Xi, Htable, ct, n);
        uint8_t lb[16]={0};
        uint64_t abits=32*8, cbits=n*8;
        for (int i=0;i<8;i++) { lb[i]=(abits>>(56-8*i))&0xff; lb[8+i]=(cbits>>(56-8*i))&0xff; }
        gcm_ghash_clmul(Xi, Htable, lb, 16);
        uint8_t S[16]; memcpy(S, Xi, 16);
        for (int i=0;i<16;i++) tag[i]=S[i]^EK[i];
    }
    dt = (now()-t0)/reps;
    printf("full path no big copy %.6f s %.1f MB/s tag0=%02x\n", dt, (n/1e6)/dt, tag[0]);

    /* EVP reference */
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int outlen; uint8_t tref[16];
    t0 = now();
    for (int r=0;r<reps;r++) {
        EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
        EVP_EncryptUpdate(ctx, ct, &outlen, pt, (int)n);
        EVP_EncryptFinal_ex(ctx, ct, &outlen);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tref);
    }
    dt = (now()-t0)/reps;
    printf("evp %.6f s %.1f MB/s\n", dt, (n/1e6)/dt);
    printf("tag match %d\n", memcmp(tag, tref, 16)==0);
    return 0;
}
