}

typedef struct {
    const __m128i *rk; uint8_t *ct; const uint8_t *pt;
    size_t start, end; __m128i ctr_swapped;
    pthread_mutex_t *mu; pthread_cond_t *cv; int *remaining;
} job_t;

static void ctr_range(job_t *j) {
    const __m128i *rk = j->rk;
    __m128i one = _mm_set_epi32(0,0,0,1);
    __m128i c = j->ctr_swapped;
    size_t off = j->start;
    while (off + 64 <= j->end) {
        __m128i c0=c, c1=_mm_add_epi32(c0,one), c2=_mm_add_epi32(c1,one), c3=_mm_add_epi32(c2,one);
        __m128i b0=_mm_xor_si128(bswap16(c0), rk[0]);
        __m128i b1=_mm_xor_si128(bswap16(c1), rk[0]);
        __m128i b2=_mm_xor_si128(bswap16(c2), rk[0]);
        __m128i b3=_mm_xor_si128(bswap16(c3), rk[0]);
        for (int r=1;r<=9;r++) {
            __m128i k=rk[r];
            b0=_mm_aesenc_si128(b0,k); b1=_mm_aesenc_si128(b1,k);
            b2=_mm_aesenc_si128(b2,k); b3=_mm_aesenc_si128(b3,k);
        }
        b0=_mm_aesenclast_si128(b0, rk[10]); b1=_mm_aesenclast_si128(b1, rk[10]);
        b2=_mm_aesenclast_si128(b2, rk[10]); b3=_mm_aesenclast_si128(b3, rk[10]);
        uint8_t *out=j->ct+off; const uint8_t *in=j->pt+off;
        _mm_storeu_si128((__m128i*)out+0, _mm_xor_si128(b0, _mm_loadu_si128((const __m128i*)in+0)));
        _mm_storeu_si128((__m128i*)out+1, _mm_xor_si128(b1, _mm_loadu_si128((const __m128i*)in+1)));
        _mm_storeu_si128((__m128i*)out+2, _mm_xor_si128(b2, _mm_loadu_si128((const __m128i*)in+2)));
        _mm_storeu_si128((__m128i*)out+3, _mm_xor_si128(b3, _mm_loadu_si128((const __m128i*)in+3)));
        off += 64; c = _mm_add_epi32(c3, one);
    }
}
static void *worker(void *a){ job_t *j=a; ctr_range(j);
    pthread_mutex_lock(j->mu); (*j->remaining)--; pthread_cond_signal(j->cv); pthread_mutex_unlock(j->mu);
    return NULL; }

int main() {
    size_t n = 60000UL*1024;
    uint8_t *pt = aligned_alloc(64, n);
    uint8_t *ct = aligned_alloc(64, n);
    memset(pt, 0x5a, n);
    uint8_t key[16]; for (int i=0;i<16;i++) key[i]=i+1;
    __m128i rk[11]; expand128(key, rk);
    uint8_t H[16]={0}, zero[16]={0};
    /* H via rk */
    {
        __m128i b = rk[0];
        for (int r=1;r<=9;r++) b=_mm_aesenc_si128(b, rk[r]);
        b=_mm_aesenclast_si128(b, rk[10]);
        _mm_storeu_si128((__m128i*)H, b);
    }
    uint8_t Hs[16]; memcpy(Hs, H, 16);
    for (int h=0;h<2;h++) for (int i=0;i<4;i++) { uint8_t t=Hs[h*8+i]; Hs[h*8+i]=Hs[h*8+7-i]; Hs[h*8+7-i]=t; }
    unsigned char Htable[256];
    unsigned long long Hll[2]; memcpy(Hll, Hs, 16);
    gcm_init_clmul(Htable, Hll);

    int nth = 2;
    size_t chunk = n/nth;
    pthread_mutex_t mu = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cv = PTHREAD_COND_INITIALIZER;
    job_t jobs[4];
    uint8_t nonce[12]={0};

    double t0 = now();
    int reps = 5;
    volatile uint8_t sink=0;
    for (int r=0;r<reps;r++) {
        int remaining = nth;
        for (int i=0;i<nth;i++) {
            jobs[i].rk=rk; jobs[i].ct=ct; jobs[i].pt=pt;
            jobs[i].start=i*chunk; jobs[i].end=(i==nth-1)?n:(i+1)*chunk;
            uint32_t c = 2 + (uint32_t)(jobs[i].start/16);
            uint8_t cb[16]={0};
            cb[15]=c&0xff; cb[14]=(c>>8)&0xff; cb[13]=(c>>16)&0xff; cb[12]=(c>>24)&0xff;
            jobs[i].ctr_swapped = bswap16(_mm_loadu_si128((const __m128i*)cb));
            jobs[i].mu=&mu; jobs[i].cv=&cv; jobs[i].remaining=&remaining;
            pthread_t th; pthread_create(&th, NULL, worker, &jobs[i]);
            pthread_detach(th);
        }
        /* ghash overlaps CTR. For a real GCM this would hash ciphertext, which isn't ready.
           Here we hash plaintext just to measure overlap bandwidth. */
        unsigned long long Xi[2]={0,0};
        gcm_ghash_clmul(Xi, Htable, pt, n);
        pthread_mutex_lock(&mu);
        while (remaining) pthread_cond_wait(&cv, &mu);
        pthread_mutex_unlock(&mu);
        sink ^= ct[0] ^ ((uint8_t*)Xi)[0];
    }
    double dt=(now()-t0)/reps;
    printf("overlap ctr2+ghash %.6f s %.1f MB/s sink %u\n", dt, (n/1e6)/dt, sink);

    /* ctr only */
    t0=now();
    for (int r=0;r<reps;r++) {
        int remaining=nth;
        for (int i=0;i<nth;i++) {
            jobs[i].start=i*chunk; jobs[i].end=(i==nth-1)?n:(i+1)*chunk;
            uint32_t c=2+(uint32_t)(jobs[i].start/16);
            uint8_t cb[16]={0};
            cb[15]=c&0xff; cb[14]=(c>>8)&0xff; cb[13]=(c>>16)&0xff; cb[12]=(c>>24)&0xff;
            jobs[i].ctr_swapped=bswap16(_mm_loadu_si128((const __m128i*)cb));
            jobs[i].remaining=&remaining;
            pthread_t th; pthread_create(&th, NULL, worker, &jobs[i]); pthread_detach(th);
        }
        pthread_mutex_lock(&mu); while (remaining) pthread_cond_wait(&cv, &mu); pthread_mutex_unlock(&mu);
        sink ^= ct[1];
    }
    dt=(now()-t0)/reps;
    printf("ctr2 only %.6f s %.1f MB/s\n", dt, (n/1e6)/dt);

    t0=now();
    for (int r=0;r<reps;r++) {
        unsigned long long Xi[2]={0,0};
        gcm_ghash_clmul(Xi, Htable, pt, n);
        sink ^= ((uint8_t*)Xi)[1];
    }
    dt=(now()-t0)/reps;
    printf("ghash only %.6f s %.1f MB/s sink %u\n", dt, (n/1e6)/dt, sink);
    return 0;
}
EOF
