static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}

/* square-and-multiply: Xi *= H^k */
static void mul_pow(unsigned long long Xi[2], unsigned char Htable[256], size_t k_blocks) {
    /* precompute powers of H by successive gmult of a running H^{2^i} stored as a block.
       We need Xi * H^k. Compute by binary method using gmult which multiplies by H (the base).
       For large k (1e6) binary method is log(k)*gmult = ~20, trivial.
       BUT gmult multiplies by the fixed H in Htable, not by an arbitrary value.
       So binary method needs multiplication by arbitrary powers, which gmult cannot do.
       Successive gmult k times is the only thing gmult supports. That's 1e6 gmults. Time it. */
    for (size_t i = 0; i < k_blocks; i++) gcm_gmult_clmul(Xi, Htable);
}

int main() {
    unsigned char H[16]; for (int i=0;i<16;i++) H[i]=i+1;
    /* bswap64 */
    for (int h=0;h<2;h++) for (int i=0;i<4;i++) { unsigned char t=H[h*8+i]; H[h*8+i]=H[h*8+7-i]; H[h*8+7-i]=t; }
    unsigned char Htable[256];
    unsigned long long Hll[2]; memcpy(Hll, H, 16);
    gcm_init_clmul(Htable, Hll);
    unsigned long long Xi[2] = {1,2};
    size_t k = 100000; /* 100k blocks ~ 1.6MB */
    double t0 = now();
    mul_pow(Xi, Htable, k);
    double dt = now()-t0;
    printf("100k gmults %.6f s  => %.1f MB-equivalent/s  Xi=%llx\n", dt, (k*16/1e6)/dt, Xi[0]);
    /* extrapolate to 1.92e6 blocks (half of 60MB) */
    printf("est for 1.92e6 gmults: %.3f s\n", dt * (1.92e6/k));
