{"command":"cd "$HOME/aesbuild" && cat > agg2.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <immintrin.h>
#include <openssl/evp.h>

void gcm_init_clmul(unsigned char Htable[16*16], const unsigned long long Xi[2]);
void gcm_ghash_clmul(unsigned long long Xi[2], const unsigned char Htable[16*16],
                     const unsigned char *inp, size_t len);
void gcm_gmult_clmul(unsigned long long Xi[2], const unsigned char Htable[16*16]);

static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}

/* Our gfmul on REFLECTED values. OpenSSL ghash uses bswap64 orientation, not full reflection.
   So to combine OpenSSL Xi values we should use OpenSSL's own multiply.
   gcm_gmult multiplies Xi by H (the one in Htable).
   To multiply by an arbitrary value we can build a temporary Htable. gcm_init_clmul is cheap. */

static void mul_by(unsigned long long Xi[2], const unsigned char factor_bswap64[16]) {
    unsigned char Htable[256];
    unsigned long long Hll[2];
    memcpy(Hll, factor_bswap64, 16);
    gcm_init_clmul(Htable, Hll);
    gcm_gmult_clmul(Xi, Htable);
}

/* compute H^k in bswap64 domain by square-and-multiply using gcm_gmult? 
   We need arbitrary multiply. mul_by does Xi *= factor where factor is already in openssl orientation.
   Square-and-multiply:
     result = 1; base = H; while k: if k&1 result *= base; base = base^2; k >>= 1
   "1" in GHASH is the field identity, which is NOT the byte 0x01 in this representation necessarily.
   For aggregation we only need H^{nblocks}, computed by successive squaring from H.
*/
static void field_sqr(unsigned char x[16]) {
    /* x = x^2, x in openssl orientation */
    unsigned long long Xi[2];
    memcpy(Xi, x, 16);
    mul_by(Xi, x);
    memcpy(x, Xi, 16);
}
static void field_mul(unsigned char x[16], const unsigned char y[16]) {
    unsigned long long Xi[2];
    memcpy(Xi, x, 16);
    mul_by(Xi, y);
    memcpy(x, Xi, 16);
}

static void pow_h(unsigned char out[16], const unsigned char H[16], size_t k) {
    /* out = H^k via square-and-multiply. Identity: start with out = H, exp = k, careful.
       result starts as identity. What's the identity element in this byte representation?
       We can avoid identity by the standard binary method that starts from the highest bit. */
    unsigned char base[16]; memcpy(base, H, 16);
    int started = 0;
    unsigned char result[16];
    for (int bit = 63; bit >= 0; bit--) {
        if (started) field_sqr(result);
        if ((k >> bit) & 1) {
            if (!started) { memcpy(result, base, 16); started = 1; }
            else field_mul(result, base);
        }
    }
    memcpy(out, result, 16);
}

int main() {
    /* Build a known message, compute full ghash and 2-partial aggregation, compare. */
    size_t n = 1024*1024; /* 1MB, multiple of 16 */
    uint8_t *data = aligned_alloc(64, n);
    for (size_t i=0;i<n;i++) data[i]=(uint8_t)(i*3);
    uint8_t H[16]; for (int i=0;i<16;i++) H[i]=i*7+3;
    /* convert to openssl orientation */
    uint8_t Hs[16]; memcpy(Hs, H, 16);
    for (int h=0;h<2;h++) for (int i=0;i<4;i++) { uint8_t t=Hs[h*8+i]; Hs[h*8+i]=Hs[h*8+7-i]; Hs[h*8+7-i]=t; }

    unsigned char Htable[256];
    unsigned long long Hll[2], Xi[2];
    memcpy(Hll, Hs, 16);
    gcm_init_clmul(Htable, Hll);

    Xi[0]=Xi[1]=0;
    gcm_ghash_clmul(Xi, Htable, data, n);
    uint8_t full[16]; memcpy(full, Xi, 16);

    size_t mid = n/2;
    unsigned long long X1[2]={0,0}, X2[2]={0,0};
    gcm_ghash_clmul(X1, Htable, data, mid);
    gcm_ghash_clmul(X2, Htable, data+mid, n-mid);

    /* aggregated = X1 * H^{mid/16} xor X2 */
    double t0 = now();
    uint8_t Hk[16];
    size_t k = mid/16;
    pow_h(Hk, Hs, k);
    double dt = now()-t0;
    printf("pow_h k=%zu took %.6f s\n", k, dt);

    unsigned long long acc[2]; memcpy(acc, X1, 16);
    mul_by(acc, Hk);
    uint8_t agg[16];
    for (int i=0;i<16;i++) agg[i] = ((uint8_t*)acc)[i] ^ ((uint8_t*)X2)[i];
    printf("match %d\n", memcmp(agg, full, 16)==0);
    if (memcmp(agg, full, 16)) {
        printf("full "); for(int i=0;i<16;i++) printf("%02x", full[i]); printf("\n");
        printf("agg  "); for(int i=0;i<16;i++) printf("%02x", agg[i]); printf("\n");
    }

    /* time pow for 60MB/2 blocks */
    t0 = now();
    pow_h(Hk, Hs, (60000UL*1024/2)/16);
    printf("pow half-60MB %.6f s\n", now()-t0);
    return 0;
}
EOF
cc -O2 -mpclmul -I/usr/local/opt/openssl@3/include -L/usr/local/opt/openssl@3/lib -o agg2 agg2.c -lcrypto && ./agg2"}

