void gcm_ghash_clmul(unsigned long long Xi[2], const unsigned char Htable[16*16], const unsigned char *inp, size_t len);
void gcm_gmult_clmul(unsigned long long Xi[2], const unsigned char Htable[16*16]);

static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}

static void mul_by(unsigned char x[16], const unsigned char factor[16]) {
    unsigned char Htable[256];
    unsigned long long Hll[2], Xi[2];
    memcpy(Hll, factor, 16);
    gcm_init_clmul(Htable, Hll);
    memcpy(Xi, x, 16);
    gcm_gmult_clmul(Xi, Htable);
    memcpy(x, Xi, 16);
}

/* H^k by successive squaring, result volatile-consumed */
static void pow_h(unsigned char out[16], const unsigned char H[16], size_t k) {
    unsigned char base[16], result[16];
    memcpy(base, H, 16);
    int started = 0;
    /* iterate bits of k from high to low */
    size_t kk = k;
    int highest = 0;
    while ((k >> highest) > 1) highest++;
    for (int bit = highest; bit >= 0; bit--) {
        if (started) {
            unsigned char tmp[16]; memcpy(tmp, result, 16);
            mul_by(result, tmp); /* result = result^2 */
        }
        if ((k >> bit) & 1) {
            if (!started) { memcpy(result, base, 16); started = 1; }
            else mul_by(result, base);
        }
    }
    memcpy(out, result, 16);
    (void)kk;
}

int main() {
    size_t n = 4096;
    uint8_t *data = aligned_alloc(64, n);
    for (size_t i=0;i<n;i++) data[i]=(uint8_t)(i*3+1);
    uint8_t H[16]; for (int i=0;i<16;i++) H[i]=i*7+3;
    uint8_t Hs[16]; memcpy(Hs, H, 16);
    for (int h=0;h<2;h++) for (int i=0;i<4;i++) { uint8_t t=Hs[h*8+i]; Hs[h*8+i]=Hs[h*8+7-i]; Hs[h*8+7-i]=t; }

    unsigned char Htable[256];
    unsigned long long Hll[2], Xi[2];
    memcpy(Hll, Hs, 16);
    gcm_init_clmul(Htable, Hll);
    Xi[0]=Xi[1]=0;
    gcm_ghash_clmul(Xi, Htable, data, n);
    uint8_t full[16]; memcpy(full, Xi, 16);

    size_t mid = n/2;
    unsigned long long X1[2]={0,0}, X2[2]={0,0};
    gcm_ghash_clmul(X1, Htable, data, mid);
    gcm_ghash_clmul(X2, Htable, data+mid, mid);

    uint8_t Hk[16];
    double t0 = now();
    pow_h(Hk, Hs, mid/16);
    printf("pow %.6f\n", now()-t0);
    /* force use */
    volatile uint8_t s = Hk[0]; (void)s;

    /* try X1 * Hk */
    uint8_t a[16]; memcpy(a, X1, 16);
    mul_by(a, Hk);
    uint8_t agg[16];
    for (int i=0;i<16;i++) agg[i]=a[i]^((uint8_t*)X2)[i];
    printf("X1*Hk xor X2 match %d\n", memcmp(agg, full, 16)==0);

    /* try Hk * X1 (swap operands): mul_by(Hk_copy, X1) */
    uint8_t b[16]; memcpy(b, Hk, 16);
    uint8_t x1b[16]; memcpy(x1b, X1, 16);
    mul_by(b, x1b);
    for (int i=0;i<16;i++) agg[i]=b[i]^((uint8_t*)X2)[i];
    printf("Hk*X1 xor X2 match %d\n", memcmp(agg, full, 16)==0);

    /* verify pow itself: H^2 should equal gmult(H) */
    uint8_t H2[16]; memcpy(H2, Hs, 16);
    mul_by(H2, Hs);
    uint8_t H2b[16]; pow_h(H2b, Hs, 2);
    printf("H^2 match %d\n", memcmp(H2, H2b, 16)==0);

    /* H^1 */
    uint8_t H1[16]; pow_h(H1, Hs, 1);
    printf("H^1 match %d\n", memcmp(H1, Hs, 16)==0);

    /* small k=1 aggregation: mid = 16 bytes */
    size_t m2 = 16;
    unsigned long long Y1[2]={0,0}, Y2[2]={0,0}, Yf[2]={0,0};
    gcm_ghash_clmul(Yf, Htable, data, 32);
    gcm_ghash_clmul(Y1, Htable, data, 16);
    gcm_ghash_clmul(Y2, Htable, data+16, 16);
    uint8_t c[16]; memcpy(c, Y1, 16);
    mul_by(c, Hs); /* * H^1 */
    uint8_t ag2[16];
    for (int i=0;i<16;i++) ag2[i]=c[i]^((uint8_t*)Y2)[i];
    uint8_t yf[16]; memcpy(yf, Yf, 16);
    printf("k=1 X1*H xor X2 match %d\n", memcmp(ag2, yf, 16)==0);
    printf("Yf "); for(int i=0;i<16;i++) printf("%02x", yf[i]); printf("\n");
    printf("ag "); for(int i=0;i<16;i++) printf("%02x", ag2[i]); printf("\n");

    /* maybe ghash output needs no extra and partials are in a different state.
       Check: ghash of 16 bytes should equal gmult of that block. */
    unsigned long long G[2]; memcpy(G, data, 16);
    gcm_gmult_clmul(G, Htable);
    unsigned long long G2[2]={0,0};
    gcm_ghash_clmul(G2, Htable, data, 16);
    printf("gmult vs ghash one block %d\n", memcmp(G, G2, 16)==0);

    return 0;
}
