#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <stdint.h>
#include <openssl/evp.h>
void gcm_init_clmul(unsigned char Htable[16*16], const unsigned long long Xi[2]);
void gcm_ghash_clmul(unsigned long long Xi[2], const unsigned char Htable[16*16], const unsigned char *inp, size_t len);
void gcm_gmult_clmul(unsigned long long Xi[2], const unsigned char Htable[16*16]);

static void mul_by(unsigned char x[16], const unsigned char factor[16]) {
    unsigned char Htable[256];
    unsigned long long Hll[2], Xi[2];
    memcpy(Hll, factor, 16);
    gcm_init_clmul(Htable, Hll);
    memcpy(Xi, x, 16);
    gcm_gmult_clmul(Xi, Htable);
    memcpy(x, Xi, 16);
}

/* compute H^k by k-1 successive multiplies for small k, and by binary for large.
   Print intermediate for k=4. */
static void pow_successive(unsigned char out[16], const unsigned char H[16], size_t k) {
    memcpy(out, H, 16);
    for (size_t i = 1; i < k; i++) mul_by(out, H);
}

static void pow_binary(unsigned char out[16], const unsigned char H[16], size_t k) {
    unsigned char result[16];
    int started = 0;
    int highest = 0;
    while ((k >> (highest+1)) && highest < 62) highest++;
    for (int bit = highest; bit >= 0; bit--) {
        if (started) {
            unsigned char sq[16];
            memcpy(sq, result, 16);
            mul_by(result, sq);
        }
        if ((k >> bit) & 1) {
            if (!started) { memcpy(result, H, 16); started = 1; }
            else mul_by(result, H);
        }
    }
    memcpy(out, result, 16);
}

int main() {
    uint8_t H[16]; for (int i=0;i<16;i++) H[i]=i*7+3;
    for (int h=0;h<2;h++) for (int i=0;i<4;i++) { uint8_t t=H[h*8+i]; H[h*8+i]=H[h*8+7-i]; H[h*8+7-i]=t; }

    for (size_t k = 1; k <= 8; k++) {
        uint8_t a[16], b[16];
        pow_successive(a, H, k);
        pow_binary(b, H, k);
