        for (int i=0;i<8;i++) { lb[i]=(abits>>(56-8*i))&0xff; lb[8+i]=(cbits>>(56-8*i))&0xff; }
        gcm_ghash_clmul(Xi, Htable, lb, 16);
        memcpy(S, Xi, 16);
    } else {
        uint8_t *gbuf = calloc(1, apad + cpad + 16);
        if (!gbuf) return -1;
        if (alen) memcpy(gbuf, aad, alen);
        if (n) memcpy(gbuf+apad, ct, n);
        uint8_t *lb = gbuf + apad + cpad;
        uint64_t abits=(uint64_t)alen*8, cbits=(uint64_t)n*8;
        for (int i=0;i<8;i++) { lb[i]=(abits>>(56-8*i))&0xff; lb[8+i]=(cbits>>(56-8*i))&0xff; }
        ghash_ossl(H, gbuf, apad+cpad+16, S);
        free(gbuf);
    }
    for (int i=0;i<16;i++) tag[i] = S[i] ^ EK[i];
    return 0;
}

static PyObject *encrypt(PyObject *self, PyObject *args) {
    Py_buffer key, nonce, pt, aad;
    if (!PyArg_ParseTuple(args, "y*y*y*y*", &key, &nonce, &pt, &aad)) return NULL;
    if (key.len != 16 && key.len != 24 && key.len != 32) {
        PyBuffer_Release(&key); PyBuffer_Release(&nonce);
        PyBuffer_Release(&pt); PyBuffer_Release(&aad);
        PyErr_SetString(PyExc_ValueError, "bad key size");
        return NULL;
    }
    /* AES-192/256 or awkward sizes: EVP fallback */
    if (key.len != 16) {
        const EVP_CIPHER *ci = key.len==24 ? EVP_aes_192_gcm() : EVP_aes_256_gcm();
        EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
        PyObject *ctobj = PyBytes_FromStringAndSize(NULL, pt.len);
        uint8_t tag[16];
        int outlen=0;
        EVP_EncryptInit_ex(ctx, ci, NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, (int)nonce.len, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key.buf, nonce.buf);
        if (aad.len) EVP_EncryptUpdate(ctx, NULL, &outlen, aad.buf, (int)aad.len);
        EVP_EncryptUpdate(ctx, (uint8_t*)PyBytes_AS_STRING(ctobj), &outlen, pt.buf, (int)pt.len);
        int total = outlen;
        EVP_EncryptFinal_ex(ctx, (uint8_t*)PyBytes_AS_STRING(ctobj)+total, &outlen);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
        EVP_CIPHER_CTX_free(ctx);
        PyBuffer_Release(&key); PyBuffer_Release(&nonce);
        PyBuffer_Release(&pt); PyBuffer_Release(&aad);
        return Py_BuildValue("NN", ctobj, PyBytes_FromStringAndSize((char*)tag, 16));
    }

    if (CT_CAP < (size_t)pt.len) {
        free(CT);
        CT_CAP = ((size_t)pt.len + 4095) & ~4095UL;
        CT = aligned_alloc(64, CT_CAP ? CT_CAP : 64);
        memset(CT, 0, CT_CAP);
    }
    uint8_t tag[16];
    if (encrypt128(key.buf, nonce.buf, nonce.len, pt.buf, pt.len, aad.buf, aad.len, CT, tag) != 0) {
        PyBuffer_Release(&key); PyBuffer_Release(&nonce);
        PyBuffer_Release(&pt); PyBuffer_Release(&aad);
        PyErr_SetString(PyExc_RuntimeError, "encrypt failed");
        return NULL;
    }
    PyObject *ct = PyBytes_FromStringAndSize((char*)CT, pt.len);
    PyBuffer_Release(&key); PyBuffer_Release(&nonce);
    PyBuffer_Release(&pt); PyBuffer_Release(&aad);
    return Py_BuildValue("NN", ct, PyBytes_FromStringAndSize((char*)tag, 16));
}

static PyMethodDef methods[] = {
    {"encrypt", encrypt, METH_VARARGS, "AES-GCM encrypt"},
    {NULL,NULL,0,NULL}
};
static struct PyModuleDef mod = {PyModuleDef_HEAD_INIT, "aesgcm_fast", NULL, -1, methods};
PyMODINIT_FUNC PyInit_aesgcm_fast(void) { return PyModule_Create(&mod); }
